using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Staff.Characters;
namespace Staff.Traversal.Editor {
[InitializeOnLoad] public static class TangentMathVerification {
 const string W="Library/TangentMath/",K="Staff.TangentMathVerify";static double start;
 static TangentMathVerification(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(W+"test.request")){File.Delete(W+"test.request");File.WriteAllText(W+"result.txt","");SessionState.SetBool(K,true);EditorApplication.isPlaying=true;return;}if(!SessionState.GetBool(K,false)||!EditorApplication.isPlaying)return;if(start==0){start=EditorApplication.timeSinceStartup;return;}if(EditorApplication.timeSinceStartup-start<4)return;try{Check();}catch(Exception e){File.AppendAllText(W+"result.txt","FAIL "+e);}finally{SessionState.SetBool(K,false);EditorApplication.isPlaying=false;start=0;}}
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);File.AppendAllText(W+"result.txt","PASS "+message+"\n");}
 static void Check(){var p=UnityEngine.Object.FindFirstObjectByType<AdventurePlayer>();var a=p.GetComponent<TangentTraversal>();var ui=p.GetComponent<TangentEquationUI>();Assert(ui,"Shared runtime equation UI installed");ui.SendMessage("LateUpdate");var canvas=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(c=>c.name=="UI - Tangent equation");Assert(canvas.renderMode==RenderMode.ScreenSpaceOverlay,"Equation uses Screen Space Overlay UI");Assert(!p.transform.parent.GetComponentsInChildren<Transform>(true).Any(t=>t.name=="LaTeX tangent equation"),"No world-space equation quad remains");ui.Measure(new Vector3(0,2,0),new Vector3(3,6,4));Assert(Mathf.Abs(ui.Slope-.8f)<.0001f&&ui.Height==6&&ui.ContactX==5,"Slope tan(theta)=rise/run; target height and horizontal contact coordinate");ui.Measure(new Vector3(0,10,0),new Vector3(3,6,4));Assert(Mathf.Abs(ui.Slope+.8f)<.0001f,"Downward tangent retains negative slope");ui.Measure(Vector3.zero,Vector3.up*10);Assert(ui.Vertical,"Vertical tangent handled without infinity");ui.Measure(new Vector3(0,2,0),new Vector3(3,-.01f,4));var tokens=(System.Collections.Generic.List<string>)typeof(TangentEquationUI).GetMethod("Tokens",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(ui,null);Assert(tokens.Contains("rightMinus")&&!tokens.Contains("right"),"Negative target height uses subtraction, never plus-minus");ui.Measure(new Vector3(0,2,0),new Vector3(3,-.001f,4));tokens=(System.Collections.Generic.List<string>)typeof(TangentEquationUI).GetMethod("Tokens",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(ui,null);Assert(tokens.Contains("right")&&!tokens.Contains("rightMinus"),"Rounded zero has no negative sign");var motion=JsonUtility.FromJson<TangentEquationUI.Motion>(Resources.Load<TextAsset>("TangentMath/motion").text);Assert(motion.frames.Length==61&&motion.frames[0].alpha<.01f&&motion.frames[60].alpha>.99f&&motion.frames[0].scale<1,"Actual Manim FadeIn animation samples loaded");Assert(Resources.Load<Texture2D>("TangentMath/9/symbol"),"LaTeX runtime numeric glyph available");a.Cancel();var body=p.GetComponent<CharacterController>();body.enabled=false;p.transform.position=new Vector3(0,1000,0);body.enabled=true;var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);cube.transform.position=new Vector3(10,1001,0);cube.transform.localScale=Vector3.one*2;cube.AddComponent<TangentSurface>();Physics.SyncTransforms();Assert(a.Aim(new Ray(p.transform.position+Vector3.up,Vector3.right)),"Test wall acquired");Assert(!ui.HasSubstitution,"No numbers while aiming");Assert(a.Launch(),"Cast begins");Assert(!ui.HasSubstitution,"No numbers during casting");Assert(a.CancelWithJump()&&a.State==TangentTraversal.Phase.Idle,"Space cancels casting immediately");a.Aim(new Ray(p.transform.position+Vector3.up,Vector3.right));a.Launch();a.TickMovement(.05f);a.TickMovement(.05f);Assert(a.State==TangentTraversal.Phase.Flying&&ui.HasSubstitution,"Numbers substituted only at flight start");Assert(a.CancelWithJump()&&a.State==TangentTraversal.Phase.Idle&&!ui.HasSubstitution,"Space cancels flight immediately and clears formula");Assert(!a.CancelWithJump(),"Normal jump remains unaffected outside traversal");UnityEngine.Object.DestroyImmediate(cube);p.Respawn();var cam=p.GetComponentInParent<Staff.Shared.SharedGameplay>().cameraController;var camera=cam.GetComponent<Camera>();Assert(a.BeginScreenAim(camera),"Aim begins");a.MoveScreenAim(Vector2.zero);a.Aim(new Ray(new Vector3(0,10000,0),Vector3.up));var position=camera.transform.position;var rotation=camera.transform.rotation;
 // Use an upward camera ray so EndScreenAim's final resample also fails.
 a.Cancel();body.enabled=false;p.transform.position=new Vector3(0,10000,0);body.enabled=true;camera.transform.position=p.transform.position+Vector3.up;camera.transform.rotation=Quaternion.LookRotation(Vector3.up,Vector3.forward);Assert(a.BeginScreenAim(camera),"Sky aim begins");position=camera.transform.position;rotation=camera.transform.rotation;Assert(!a.EndScreenAim(),"Invalid aim does not launch");cam.Simulate(.016f);Assert(Vector3.Distance(position,camera.transform.position)<.001f&&Quaternion.Angle(rotation,camera.transform.rotation)<.01f,"First release frame preserves camera pose; no snap");for(int i=0;i<20;i++)cam.Simulate(.016f);Assert(!a.IsScreenAiming,"Normal camera resumes after blend");var nearSize=TangentEquationUI.DisplaySize(camera,camera.transform.position+camera.transform.forward*10);var farSize=TangentEquationUI.DisplaySize(camera,camera.transform.position+camera.transform.forward*300);Assert(Mathf.Abs(nearSize.x/nearSize.y-6)<.001f&&Mathf.Abs(farSize.x/farSize.y-6)<.001f&&farSize.y>=24,"Original 6:1 ratio retained; UI minimum is 144 by 24 pixels");
 }
}
}
